import {
  type PickerAppearance,
  type PickerItemValue,
  Picker as PickerPrimitive,
} from "@expo/ui";
import {
  Children,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";
import {
  type GestureResponderEvent,
  Platform,
  Pressable,
  type PressableProps,
  View,
} from "react-native";
import Animated, {
  Easing,
  interpolate,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import { cn } from "@/lib/utils";
import { ActionInput } from "../action-input";
import {
  BottomSheet,
  BottomSheetBody,
  BottomSheetContent,
  BottomSheetFooter,
  BottomSheetHeader,
  BottomSheetTitle,
} from "../bottom-sheet";
import { ChevronDownIcon } from "../icons";
import {
  InputAddon,
  type InputAddonChild,
  type InputAddonChildren,
  InputAddonIcon,
  useInputAddons,
} from "../input";
import { Slot } from "../slot";
import {
  NativeSelectAndroidHost,
  NativeSelectContentMenu,
  NativeSelectTriggerAnchor,
} from "./native-select-input";
import { NativeSelectPicker } from "./native-select-picker";

// Constants
const ANIMATION_DURATION = 280;
const ANIMATION_EASING = Easing.out(Easing.cubic);
const NATIVE_SELECT_INPUT_NAME = "NativeSelectInput";
const NATIVE_SELECT_TRIGGER_NAME = "NativeSelectTrigger";
const NATIVE_SELECT_CONTENT_NAME = "NativeSelectContent";
const NATIVE_SELECT_SHEET_FOOTER_NAME = "NativeSelectSheetFooter";
const WHEEL_PICKER_HEIGHT = 216;
const DEFAULT_PLACEHOLDER = "Select...";

type NativeSelectVariant = PickerAppearance;

// Types
type NativeSelectItemData<T extends PickerItemValue> = {
  label: string;
  value: T;
};

type NativeSelectContextProps<T extends PickerItemValue> = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  value?: T;
  onValueChange: (value: T) => void;
  selectedValue?: T;
  setSelectedValue: (value: T) => void;
  onConfirm: (value?: T) => void;
  onCancel: () => void;
  disabled?: boolean;
  items: NativeSelectItemData<T>[];
  itemElements: React.ReactElement[];
  setItemElements: (elements: React.ReactElement[]) => void;
  placeholder: string;
  setPlaceholder: (placeholder: string) => void;
  variant: NativeSelectVariant;
  setVariant: (variant: NativeSelectVariant) => void;
  hasTrigger: boolean;
  hasInput: boolean;
  className?: string;
  testID?: string;
};

type NativeSelectProps<T extends PickerItemValue> = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  value?: T;
  onValueChange?: (value: T) => void;
  disabled?: boolean;
  variant?: NativeSelectVariant;
  className?: string;
  testID?: string;
  children: React.ReactNode;
};

type NativeSelectInputProps = Partial<
  React.ComponentProps<typeof ActionInput>
> & {
  variant?: NativeSelectVariant;
  placeholder?: string;
  children?: React.ReactNode;
};

type NativeSelectTriggerProps = PressableProps & {
  asChild?: boolean;
};

type NativeSelectContentProps = {
  children?: React.ReactNode;
};

type NativeSelectSheetConfirmProps = PressableProps & {
  asChild?: boolean;
};

// Context
const NativeSelectContext =
  createContext<NativeSelectContextProps<PickerItemValue> | null>(null);

const useNativeSelect = () => {
  const context = useContext(NativeSelectContext);
  if (!context) {
    throw new Error("useNativeSelect must be used within a NativeSelect");
  }
  return context;
};

// Helpers
const getDisplayName = (type: React.ReactElement["type"]) => {
  if (typeof type === "string" || !("displayName" in type)) {
    return;
  }
  return type.displayName;
};

const extractNativeSelectItems = <T extends PickerItemValue>(
  children: React.ReactNode
): NativeSelectItemData<T>[] => {
  const items: NativeSelectItemData<T>[] = [];

  for (const child of Children.toArray(children)) {
    if (!isValidElement(child) || child.type !== NativeSelectItem) {
      continue;
    }

    const { label, value } = child.props as NativeSelectItemData<T>;
    items.push({ label, value });
  }

  return items;
};

const splitNativeSelectContentChildren = (children: React.ReactNode) => {
  const itemElements: React.ReactElement[] = [];
  let sheetFooter: React.ReactElement | undefined;

  for (const child of Children.toArray(children)) {
    if (!isValidElement(child)) {
      continue;
    }

    if (child.type === NativeSelectItem) {
      itemElements.push(child);
      continue;
    }

    if (
      child.type === NativeSelectSheetFooter ||
      getDisplayName(child.type) === NATIVE_SELECT_SHEET_FOOTER_NAME
    ) {
      sheetFooter = child;
    }
  }

  return { itemElements, sheetFooter };
};

const getNativeSelectFormFlags = (children: React.ReactNode) => {
  let hasTrigger = false;
  let hasInput = false;
  let inputVariant: NativeSelectVariant | undefined;

  const visit = (node: React.ReactNode) => {
    for (const child of Children.toArray(node)) {
      if (!isValidElement(child)) {
        continue;
      }

      const name = getDisplayName(child.type);
      if (name === NATIVE_SELECT_TRIGGER_NAME) {
        hasTrigger = true;
      }
      if (name === NATIVE_SELECT_INPUT_NAME) {
        hasInput = true;
        const props = child.props as { variant?: NativeSelectVariant };
        inputVariant = props.variant ?? "wheel";
      }

      if (
        child.props &&
        typeof child.props === "object" &&
        "children" in child.props
      ) {
        visit((child.props as { children?: React.ReactNode }).children);
      }
    }
  };

  visit(children);

  return { hasInput, hasTrigger, inputVariant };
};

// Components
export const NativeSelectItem = PickerPrimitive.Item;

/**
 * Native single-selection input built on Expo UI Picker.
 * Always compose with NativeSelectContent. Optionally add Trigger and Input.
 */
export const NativeSelect = <T extends PickerItemValue>({
  open: openProp,
  onOpenChange: onOpenChangeProp,
  value: valueProp,
  onValueChange: onValueChangeProp,
  disabled,
  variant: variantProp = "menu",
  className,
  testID,
  children,
}: NativeSelectProps<T>) => {
  const [internalOpen, setInternalOpen] = useState(openProp ?? false);
  const [internalValue, setInternalValue] = useState<T>();
  const [selectedValue, setSelectedValue] = useState<T>();
  const [itemElements, setItemElements] = useState<React.ReactElement[]>([]);
  const [placeholder, setPlaceholder] = useState(DEFAULT_PLACEHOLDER);
  // Seeded from root or Input; Input can still override. Do not re-sync from
  // root props or an Input override will be overwritten.
  const { hasTrigger, hasInput, inputVariant } = useMemo(
    () => getNativeSelectFormFlags(children),
    [children]
  );
  const hasFormUi = hasTrigger || hasInput;
  const [variant, setVariant] = useState<NativeSelectVariant>(
    () => inputVariant ?? (hasFormUi ? "wheel" : variantProp)
  );

  const items = useMemo(
    () => extractNativeSelectItems<T>(itemElements),
    [itemElements]
  );

  const isOpenControlled = openProp !== undefined;
  const open = isOpenControlled ? openProp : internalOpen;

  const isValueControlled = valueProp !== undefined;
  const value = isValueControlled ? valueProp : internalValue;

  useEffect(() => {
    if (value !== undefined) {
      setSelectedValue(value);
    }
  }, [value]);

  const onOpenChange = useCallback(
    (nextOpen: boolean) => {
      if (!isOpenControlled) {
        setInternalOpen(nextOpen);
      }
      onOpenChangeProp?.(nextOpen);
    },
    [isOpenControlled, onOpenChangeProp]
  );

  const onValueChange = useCallback(
    (nextValue: T) => {
      if (!isValueControlled) {
        setInternalValue(nextValue);
      }
      onValueChangeProp?.(nextValue);
    },
    [isValueControlled, onValueChangeProp]
  );

  const onConfirm = useCallback(
    (nextValue?: T) => {
      const finalValue = nextValue ?? selectedValue;

      if (typeof finalValue !== "undefined") {
        onValueChange(finalValue);
      }

      onOpenChange(false);
    },
    [onOpenChange, onValueChange, selectedValue]
  );

  const onCancel = useCallback(() => {
    if (value !== undefined) {
      setSelectedValue(value);
    }
    onOpenChange(false);
  }, [onOpenChange, value]);

  const ctx = useMemo(
    () => ({
      className,
      disabled,
      hasInput,
      hasTrigger,
      itemElements,
      items,
      onCancel,
      onConfirm,
      onOpenChange,
      onValueChange,
      open,
      placeholder,
      selectedValue,
      setItemElements,
      setPlaceholder,
      setSelectedValue,
      setVariant,
      testID,
      value,
      variant,
    }),
    [
      className,
      disabled,
      hasInput,
      hasTrigger,
      itemElements,
      items,
      onCancel,
      onConfirm,
      onOpenChange,
      onValueChange,
      open,
      placeholder,
      selectedValue,
      testID,
      value,
      variant,
    ]
  );

  return (
    <NativeSelectContext.Provider
      value={ctx as NativeSelectContextProps<T | PickerItemValue>}
    >
      {Platform.OS === "android" && hasFormUi ? (
        <NativeSelectAndroidHost
          disabled={disabled}
          onOpenChange={onOpenChange}
          open={open}
        >
          {children}
        </NativeSelectAndroidHost>
      ) : (
        children
      )}
    </NativeSelectContext.Provider>
  );
};

export const NativeSelectTrigger = ({
  asChild,
  onPress: onPressProp,
  ...props
}: NativeSelectTriggerProps) => {
  const {
    disabled,
    open,
    onOpenChange,
    value,
    items,
    selectedValue,
    setSelectedValue,
  } = useNativeSelect();

  const handlePress = useCallback(
    (event: GestureResponderEvent) => {
      onPressProp?.(event);

      if (disabled) {
        return;
      }

      const committedValue = value ?? items.at(0)?.value;
      const seedValue = selectedValue ?? committedValue;
      if (seedValue !== undefined) {
        setSelectedValue(seedValue);
      }

      if (Platform.OS === "android") {
        onOpenChange(!open);
        return;
      }

      onOpenChange(true);
    },
    [
      disabled,
      items,
      onOpenChange,
      onPressProp,
      open,
      selectedValue,
      setSelectedValue,
      value,
    ]
  );

  const Comp = asChild ? Slot.Pressable : Pressable;

  return (
    <NativeSelectTriggerAnchor disabled={disabled}>
      <Comp {...props} disabled={disabled} onPress={handlePress} />
    </NativeSelectTriggerAnchor>
  );
};

NativeSelectTrigger.displayName = NATIVE_SELECT_TRIGGER_NAME;

/**
 * Form-styled native select input.
 * - Default / wheel: display-only ActionInput (open via NativeSelectTrigger)
 * - iOS `menu`: non-pressable input shell; only the native menu picker is interactive
 */
export const NativeSelectInput = ({
  variant = "wheel",
  placeholder = DEFAULT_PLACEHOLDER,
  className,
  testID,
  children,
  ...props
}: NativeSelectInputProps) => {
  const {
    open,
    value,
    onValueChange,
    items,
    itemElements,
    disabled,
    setPlaceholder,
    setVariant,
  } = useNativeSelect();

  const addonElements = useMemo(() => {
    const addons: InputAddonChild[] = [];
    for (const child of Children.toArray(children)) {
      if (isValidElement(child) && child.type === InputAddon) {
        addons.push(child as InputAddonChild);
      }
    }
    return addons;
  }, [children]);

  const { startAddons, endAddons, pressableClassName } = useInputAddons(
    addonElements as InputAddonChildren
  );

  useLayoutEffect(() => {
    setPlaceholder(placeholder);
  }, [placeholder, setPlaceholder]);

  useLayoutEffect(() => {
    setVariant(variant);
  }, [variant, setVariant]);

  const committedValue = value ?? items.at(0)?.value;

  const valueLabel = useMemo(() => {
    if (committedValue === undefined) {
      return;
    }
    return items.find((item) => item.value === committedValue)?.label;
  }, [items, committedValue]);

  const openSharedValue = useSharedValue(open ? 1 : 0);

  useEffect(() => {
    openSharedValue.value = withTiming(open ? 1 : 0, {
      duration: ANIMATION_DURATION,
      easing: ANIMATION_EASING,
    });
  }, [open, openSharedValue]);

  const animatedStyle = useAnimatedStyle(() => {
    const rotate = interpolate(openSharedValue.value, [0, 1], [0, 180]);
    return {
      transform: [{ rotate: `${rotate}deg` }],
    };
  });

  if (Platform.OS === "ios" && variant === "menu") {
    if (committedValue === undefined) {
      return null;
    }

    return (
      <View
        className={cn(
          "flex min-h-12 w-full flex-row items-center gap-2 rounded-lg border border-input bg-background py-2 pr-0 pl-3",
          disabled && "opacity-50",
          pressableClassName,
          className
        )}
        pointerEvents="box-none"
      >
        {startAddons}

        <View className="min-w-0 grow" />

        <InputAddon align="inline-end">
          <NativeSelectPicker
            appearance="menu"
            enabled={!disabled}
            onValueChange={onValueChange}
            selectedValue={committedValue}
            testID={testID}
          >
            {itemElements}
          </NativeSelectPicker>
        </InputAddon>

        {endAddons}
      </View>
    );
  }

  const sheetInputAddons = [
    ...startAddons,
    <InputAddon align="inline-end" key="native-select-chevron">
      <Animated.View style={animatedStyle}>
        <InputAddonIcon>
          <ChevronDownIcon />
        </InputAddonIcon>
      </Animated.View>
    </InputAddon>,
    ...endAddons,
  ] as InputAddonChildren;

  return (
    <ActionInput
      {...props}
      className={cn(pressableClassName, className)}
      disabled={disabled}
      focused={open}
      placeholder={placeholder}
      testID={testID}
      value={valueLabel}
    >
      {sheetInputAddons}
    </ActionInput>
  );
};

NativeSelectInput.displayName = NATIVE_SELECT_INPUT_NAME;

/**
 * Presentation surface for the native select. Always required.
 * - Content-only: inline Expo Picker (variant from root)
 * - iOS wheel + form UI: bottom sheet with wheel picker
 * - iOS menu + Input: registers items only (picker lives in NativeSelectInput)
 * - Android + form UI: ExposedDropdownMenu items
 */
export const NativeSelectContent = ({ children }: NativeSelectContentProps) => {
  const {
    open,
    onOpenChange,
    value,
    onValueChange,
    selectedValue,
    setSelectedValue,
    onCancel,
    disabled,
    variant,
    placeholder,
    setItemElements,
    hasTrigger,
    hasInput,
    className,
    testID,
  } = useNativeSelect();

  const hasFormUi = hasTrigger || hasInput;

  const { itemElements, sheetFooter } = useMemo(
    () => splitNativeSelectContentChildren(children),
    [children]
  );
  const items = useMemo(
    () => extractNativeSelectItems(itemElements),
    [itemElements]
  );

  useLayoutEffect(() => {
    setItemElements(itemElements);
  }, [itemElements, setItemElements]);

  const requiresConfirm =
    Platform.OS === "ios" && variant === "wheel" && Boolean(sheetFooter);
  const committedValue = value ?? items.at(0)?.value;
  const draftValue = selectedValue ?? committedValue;
  const pickerValue = requiresConfirm ? draftValue : committedValue;

  const handlePickerValueChange = useCallback(
    (nextValue: PickerItemValue) => {
      if (requiresConfirm) {
        setSelectedValue(nextValue);
        return;
      }
      onValueChange(nextValue);
    },
    [onValueChange, requiresConfirm, setSelectedValue]
  );

  if (!hasFormUi) {
    if (committedValue === undefined) {
      return null;
    }

    return (
      <NativeSelectPicker
        appearance={variant}
        className={className}
        enabled={!disabled}
        onValueChange={onValueChange}
        selectedValue={committedValue}
        testID={testID}
      >
        {itemElements}
      </NativeSelectPicker>
    );
  }

  // Menu picker is embedded in Input; Content only registers items.
  if (Platform.OS === "ios" && variant === "menu" && hasInput) {
    return null;
  }

  if (Platform.OS === "android") {
    return (
      <NativeSelectContentMenu
        disabled={disabled}
        items={items}
        onOpenChange={onOpenChange}
        onValueChange={onValueChange}
        open={open}
        selectedValue={committedValue}
      />
    );
  }

  if (pickerValue === undefined) {
    return null;
  }

  return (
    <BottomSheet
      onOpenChange={requiresConfirm ? onCancel : onOpenChange}
      open={open}
    >
      <BottomSheetContent>
        <BottomSheetHeader>
          <BottomSheetTitle>{placeholder}</BottomSheetTitle>
        </BottomSheetHeader>
        <BottomSheetBody className={sheetFooter ? undefined : "pb-4"}>
          <NativeSelectPicker
            appearance="wheel"
            enabled={!disabled}
            matchContents={false}
            onValueChange={handlePickerValueChange}
            selectedValue={pickerValue}
            style={{ height: WHEEL_PICKER_HEIGHT, width: "100%" }}
            testID={testID}
          >
            {itemElements}
          </NativeSelectPicker>
        </BottomSheetBody>
        {sheetFooter}
      </BottomSheetContent>
    </BottomSheet>
  );
};

NativeSelectContent.displayName = NATIVE_SELECT_CONTENT_NAME;

export const NativeSelectSheetFooter = (
  props: React.ComponentProps<typeof BottomSheetFooter>
) => {
  return <BottomSheetFooter {...props} />;
};

NativeSelectSheetFooter.displayName = NATIVE_SELECT_SHEET_FOOTER_NAME;

export const NativeSelectSheetConfirm = ({
  asChild,
  onPress: onPressProp,
  ...props
}: NativeSelectSheetConfirmProps) => {
  const { onConfirm } = useNativeSelect();

  const onPress = useCallback(
    (event: GestureResponderEvent) => {
      onPressProp?.(event);
      onConfirm();
    },
    [onConfirm, onPressProp]
  );

  const Comp = asChild ? Slot.Pressable : Pressable;

  return <Comp {...props} onPress={onPress} />;
};

import type { PickerItemValue } from "@expo/ui";

type NativeSelectAndroidHostProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
};

type NativeSelectTriggerAnchorProps = {
  disabled?: boolean;
  children: React.ReactElement;
};

type NativeSelectContentMenuProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  disabled?: boolean;
  selectedValue?: PickerItemValue;
  onValueChange: (value: PickerItemValue) => void;
  items: { label: string; value: PickerItemValue }[];
};

/** Default stub — Metro resolves the `.android` file on Android. */
export const NativeSelectAndroidHost = ({
  children,
}: NativeSelectAndroidHostProps) => {
  return <>{children}</>;
};

/** Default stub — Metro resolves the `.android` file on Android. */
export const NativeSelectTriggerAnchor = ({
  children,
}: NativeSelectTriggerAnchorProps) => {
  return <>{children}</>;
};

/** Default stub — Metro resolves the `.android` file on Android. */
export const NativeSelectContentMenu = (
  _props: NativeSelectContentMenuProps
) => {
  return null;
};

import type { PickerItemValue } from "@expo/ui";
import {
  DropdownMenuItem,
  ExposedDropdownMenu,
  ExposedDropdownMenuBox,
  Host,
  RNHostView,
  Text as TextPrimitive,
} from "@expo/ui/jetpack-compose";
import { menuAnchor } from "@expo/ui/jetpack-compose/modifiers";
import { View } from "react-native";
import { useCSSVariable } from "uniwind";

// Must match InputPressable's focused/invalid outlineWidth. Outline paints
// outside layout; RNHostView/AndroidView clips to the hosted child's bounds.
const INPUT_OUTLINE_MAX_WIDTH = 2;

type NativeSelectAndroidHostProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
};

/**
 * Wraps Trigger + Content so ExposedDropdownMenuBox can own both the anchor and menu.
 *
 * @see https://docs.expo.dev/versions/latest/sdk/ui/jetpack-compose/exposeddropdownmenubox/
 */
export const NativeSelectAndroidHost = ({
  open,
  onOpenChange,
  disabled,
  children,
}: NativeSelectAndroidHostProps) => {
  return (
    <Host
      matchContents
      style={{
        alignSelf: "stretch",
        margin: -INPUT_OUTLINE_MAX_WIDTH,
        width: "100%",
      }}
    >
      <ExposedDropdownMenuBox
        expanded={open}
        onExpandedChange={disabled ? undefined : onOpenChange}
      >
        {children}
      </ExposedDropdownMenuBox>
    </Host>
  );
};

type NativeSelectTriggerAnchorProps = {
  disabled?: boolean;
  children: React.ReactElement;
};

/** Anchors the Android ExposedDropdownMenu to the Trigger child. */
export const NativeSelectTriggerAnchor = ({
  disabled,
  children,
}: NativeSelectTriggerAnchorProps) => {
  return (
    <RNHostView
      matchContents
      modifiers={[menuAnchor("primaryNotEditable", !disabled)]}
    >
      <View
        style={{
          alignSelf: "stretch",
          padding: INPUT_OUTLINE_MAX_WIDTH,
          width: "100%",
        }}
      >
        {children}
      </View>
    </RNHostView>
  );
};

type NativeSelectContentMenuProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  disabled?: boolean;
  selectedValue?: PickerItemValue;
  onValueChange: (value: PickerItemValue) => void;
  items: { label: string; value: PickerItemValue }[];
};

/** Renders the Android ExposedDropdownMenu item list. */
export const NativeSelectContentMenu = ({
  open,
  onOpenChange,
  disabled,
  selectedValue,
  onValueChange,
  items,
}: NativeSelectContentMenuProps) => {
  const foregroundColor = useCSSVariable("--color-foreground") as string;
  const popoverColor = useCSSVariable("--color-popover") as string;

  return (
    <ExposedDropdownMenu
      containerColor={popoverColor}
      expanded={open}
      onDismissRequest={() => onOpenChange(false)}
    >
      {items.map((item) => {
        const isSelected = item.value === selectedValue;

        return (
          <DropdownMenuItem
            enabled={!disabled}
            key={String(item.value)}
            onClick={
              disabled
                ? undefined
                : () => {
                    onValueChange(item.value);
                    onOpenChange(false);
                  }
            }
          >
            <DropdownMenuItem.Text>
              <TextPrimitive color={foregroundColor}>
                {item.label}
              </TextPrimitive>
            </DropdownMenuItem.Text>
            {isSelected ? (
              <DropdownMenuItem.TrailingIcon>
                <TextPrimitive color={foregroundColor}>✓</TextPrimitive>
              </DropdownMenuItem.TrailingIcon>
            ) : null}
          </DropdownMenuItem>
        );
      })}
    </ExposedDropdownMenu>
  );
};

import {
  Host as HostPrimitive,
  type PickerAppearance,
  type PickerItemValue,
  Picker as PickerPrimitive,
} from "@expo/ui";
import { withUniwind } from "uniwind";
import { cn } from "@/lib/utils";

const StyledHost = withUniwind(HostPrimitive);

export type NativeSelectPickerProps<T extends PickerItemValue> = {
  appearance?: PickerAppearance;
  selectedValue: T;
  onValueChange: (value: T) => void;
  enabled?: boolean;
  className?: string;
  style?: React.ComponentProps<typeof HostPrimitive>["style"];
  testID?: string;
  matchContents?: boolean;
  children: React.ReactNode;
};

export const NativeSelectPicker = <T extends PickerItemValue>({
  appearance = "menu",
  selectedValue,
  onValueChange,
  enabled = true,
  className,
  style,
  testID,
  matchContents = true,
  children,
}: NativeSelectPickerProps<T>) => {
  return (
    <StyledHost
      className={cn(className)}
      matchContents={matchContents}
      style={style}
    >
      <PickerPrimitive
        appearance={appearance}
        enabled={enabled}
        onValueChange={onValueChange}
        selectedValue={selectedValue}
        testID={testID}
      >
        {children}
      </PickerPrimitive>
    </StyledHost>
  );
};

import {
  Host as HostPrimitive,
  type PickerAppearance,
  type PickerItemValue,
} from "@expo/ui";
import { Picker as SwiftUIPicker, Text } from "@expo/ui/swift-ui";
import {
  disabled as disabledModifier,
  type ModifierConfig,
  pickerStyle,
  tag,
  tint,
} from "@expo/ui/swift-ui/modifiers";
import { Children, isValidElement } from "react";
import { useCSSVariable, withUniwind } from "uniwind";
import { cn } from "@/lib/utils";

const StyledHost = withUniwind(HostPrimitive);

export type NativeSelectPickerProps<T extends PickerItemValue> = {
  appearance?: PickerAppearance;
  selectedValue: T;
  onValueChange: (value: T) => void;
  enabled?: boolean;
  className?: string;
  style?: React.ComponentProps<typeof HostPrimitive>["style"];
  testID?: string;
  matchContents?: boolean;
  children: React.ReactNode;
};

type PickerItemProps<T extends PickerItemValue> = {
  label: string;
  value: T;
};

const extractItems = <T extends PickerItemValue>(children: React.ReactNode) => {
  const items: PickerItemProps<T>[] = [];

  for (const child of Children.toArray(children)) {
    if (!isValidElement(child)) {
      continue;
    }

    const { label, value } = child.props as PickerItemProps<T>;
    if (typeof label !== "string" || value === undefined) {
      continue;
    }

    items.push({ label, value });
  }

  return items;
};

export const NativeSelectPicker = <T extends PickerItemValue>({
  appearance = "menu",
  selectedValue,
  onValueChange,
  enabled = true,
  className,
  style,
  testID,
  matchContents = true,
  children,
}: NativeSelectPickerProps<T>) => {
  const primaryColor = useCSSVariable("--color-primary") as string;
  const items = extractItems<T>(children);

  const modifiers: ModifierConfig[] = [
    pickerStyle(appearance === "wheel" ? "wheel" : "menu"),
    tint(primaryColor),
  ];

  if (!enabled) {
    modifiers.push(disabledModifier(true));
  }

  return (
    <StyledHost
      className={cn(className)}
      matchContents={matchContents}
      style={style}
    >
      <SwiftUIPicker
        modifiers={modifiers}
        onSelectionChange={(value) => onValueChange(value as T)}
        selection={selectedValue}
        testID={testID}
      >
        {items.map((item) => (
          <Text key={String(item.value)} modifiers={[tag(item.value)]}>
            {item.label}
          </Text>
        ))}
      </SwiftUIPicker>
    </StyledHost>
  );
};
